 function exportText(project){const p=C.normalizeProject(project);return [p.title,'='.repeat(Math.min(p.title.length+8,50)),...p.pages.flatMap((page,i)=>['',`[${i+1}/${p.pages.length}] ${page.tab}`,'-'.repeat(30),...page.elements.flatMap(el=>{if(el.type==='shape'||el.type==='image')return [];if(el.type==='table')return [el.text,...(el.data.rows||[]).map(row=>row.join(' | '))];if(el.type==='stat'){const spec=root.DocutStatCharts.lookup[el.data?.kind];return [el.text,'차트 유형: '+(spec?.name||''),'자료 열: '+(spec?.columns||[]).join(' | '),...((el.data?.rows||[]).map(row=>row.join(' | '))),...(el.data?.kind==='control'?['관리 한계: '+JSON.stringify(el.data.limits||{})]:[]),...(el.data?.kind==='forest'?['비교 기준선: '+(el.data.referenceValue===null?'[미입력]':el.data.referenceValue)]:[]),'단위: '+(el.unit||'[미입력]')+' | 팔레트: '+(el.data?.palette||'default'),'출처: '+(el.source||'[미입력]')+' | 기준일: '+(el.asOfDate||'[미입력]')+' | 근거: '+(el.evidence||'[미입력]')+' | 검증: '+(el.verified?'사용자 확인':'미확인')];}if(['bar','line','donut'].includes(el.type))return [el.text,(el.data.labels||[]).map((label,j)=>label+': '+el.data.values[j]).join(' / ')];return [el.text]})])].join('\n');}
 function aiPrompt(project){const p=C.normalizeProject(project);const review=root.DocutQualityReview?.analyze(p);
  // Advisory findings are not factual corrections: include a bounded review only.
  const QA=review?'[자동 품질 점검 · 사실 검증 아님]\n'+review.pages.map(pg=>`${pg.index+1}. 현재 ${pg.title} / 권장 역할 ${pg.suggested}`).join('\n')+'\n'+review.issues.slice(0,45).map(it=>`${it.pageIndex+1}쪽: ${it.message} / ${it.hint}`).join('\n')+(review.total>45?`\n나머지 ${review.total-45}건은 DoCut 점검 TXT에서 확인`:''):'자동 점검 정보 없음';
 return `당신은 임원·공공기관 보고서 설계 전문가입니다. 아래 DoCut 스토리보드에서 결론→근거→비교→대안→실행의 논리 흐름을 개선한 ${p.frame?.label||'16:9'} (${p.frame?.width||1280}×${p.frame?.height||720}) HTML 보고서를 제작하세요.\n\n필수 지침:\n- 반드시 각 페이지의 탭 제목과 메시지 계층을 준수하되 근거가 부족한 숫자·사실은 만들지 말 것.
- 통계 차트의 kind/rows/limits/referenceValue/단위/출처를 새로 추정하거나 조작하지 말 것. 원자료가 비어 있으면 빈 차트 상태로 유지하고, 요약에서 일부 행이 생략됐으면 전체 데이터가 든 DoCut 프로젝트 JSON을 별도로 확인할 것.\n- 제목은 결론 중심의 짧은 문장, 본문은 근거와 시사점 중심. 모든 도표에는 의미 있는 라벨을 포함할 것.\n- 현재 배치 위치/크기와 디자인 프리셋(${p.theme})을 최대한 보존하고 필요한 경우만 조정.\n- 기존 요소의 고유 ID, source(원문 출처), asOfDate(기준일), unit(단위), evidence(근거·산식)는 삭제하거나 임의로 고쳐 쓰지 말 것. 자료 미확인 시 verified=false 유지.\n- 수정이 필요한 페이지만 제안하고, 검증한 것으로 거짓 표기하지 말 것. 응답이 DoCut 편집용이라면 schema=3 프로젝트 JSON으로 제시.\n- 콘텐츠는 정교한 캡션과 같은 편집 가능한 텍스트 구조로 제작. 각 요소에 지정된 모션 최대 3개를 부드럽게 순서대로 적용. 무한 GPU 애니메이션 금지.\n- 기본 화면 내 스크롤 없이 16:9 한 페이지씩 표시, Ctrl+←/→와 Ctrl+1~4 페이지 이동, 모바일 화면 대응.\n- 접근성, reduced-motion, 단독 실행 가능한 HTML, 안전한 텍스트 입력을 준수.\n- 외부 폰트 또는 서버에 의존하지 않으며 Pretendard 우선·시스템 폴백.\n\n${QA}\n\n[프로젝트]\n${p.title}\n\n[페이지별 구성]\n${p.pages.map((page,i)=>`${i+1}. ${page.tab}\n${page.elements.map(b=>`  - [${b.type}] ${b.text.replace(/\n/g,' / ').slice(0,240)}${b.type==='stat'?` (통계:${b.data.kind}, 원자료:${b.data.rows.length}행, ${root.DocutStatCharts.lookup[b.data.kind]?.columns.join(' / ')||''}, 관리 한계:${JSON.stringify(b.data.limits||{})}, 비교 기준:${b.data.referenceValue===null?'미입력':b.data.referenceValue}, 원자료 앞 12행:${JSON.stringify(b.data.rows.slice(0,12))}${b.data.rows.length>12?' [전체 '+b.data.rows.length+'행은 프로젝트 JSON 참조]':''})`:''} | 위치(${Math.round(b.x)},${Math.round(b.y)}) 크기(${Math.round(b.w)}x${Math.round(b.h)}) | 출처:${b.source||'[미기입]'} 기준일:${b.asOfDate||'[미기입]'} 단위:${b.unit||b.data?.unit||'[미기입]'} 근거:${(b.evidence||'').replace(/\n/g,' ').slice(0,160)} 검증:${b.verified?'사용자 확인':'미확인'} | 모션: ${b.effects.map(e=>e.kind+' '+e.duration+'ms').join(' → ')||'없음'}`).join('\n')}`).join('\n\n')}\n\n확인되지 않은 수치에는 [자료 확인 필요]로 표시하세요.`;}
 function downloadFile(filename,content,mime='text/plain;charset=utf-8'){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
